/**
 * FlightSimulator - simple 2D flight simulator with intentional bugs.
 * @param {string} canvasId - ID of a 500x500 px canvas element.
 *
 * IMPORTANT: The bugs introduced below are intentional and documented within
 * the code. This implementation is meant for demonstration only.
 */
function FlightSimulator(canvasId) {
    // ==========================================================
    //   INITIAL SETUP: GLIDEOVER RENDER LOOP AND STATE
    // ==========================================================
    const canvas = document.getElementById(canvasId);
    if (!canvas || canvas.width !== 500 || canvas.height !== 500) {
        console.error('Canvas must exist and be 500x500 px.');
        return;
    }
    const ctx = canvas.getContext('2d');

    // Physics and state
    let state = {
        // Position & velocity (in arbitrary units; 1 px ~ 30 ft)
        alt: 5000,          // current altitude (ft)
        speed: 250,         // ground speed (knots)
        throttle: 50,       // % throttle
        enginePower: 1.0,   // engine power factor (0..1)
        pitch: 0,           // degrees relative to horizon
        roll: 0,            // roll angle (bank) degrees
        yaw: 0,             // heading degrees
        // Simulated orientation velocities
        pitchRate: 0,       // degrees per second
        rollRate: 0,        // degrees per second
        yawRate: 0,         // degrees per second
        // Fuel
        fuel: 1000          // liters
    };

    // Instrument readings (may lag or be sticky)
    let instruments = {
        speed: state.speed,
        alt: state.alt,
        heading: state.yaw,
        throttle: state.throttle,
        enginePower: state.enginePower
    };

    // BUG FLAGS
    let bugs = {
        instrumentLag: false,
        altStuck: false,
        compassDrift: false,
        engineFluct: false
    };

    // Timers for lag and stickiness
    let lagTimer = 0;
    let altStickTimer = 0;
    let compassTimer = 0;
    let engineTimer = 0;

    // Constants
    const FPS = 60;
    const dt = 1 / FPS;
    const THROTTLE_STEP = 2;          // % per key press
    const PITCH_STEP = 0.5;           // degrees per key press
    const YAW_STEP = 1;               // degrees per key press
    const ROLL_STEP = 1;              // degrees per key press
    const MAX_SPEED = 400;
    const MAX_ALT = 40000;
    const MIN_ALT = 0;
    const GAS = 0.001;                // g per unit speed for education purposes
    const MAG_ANECHO = [30, 90, 210, 330]; // headings with anomaly influence

    // ==========================================================
    //   INPUT HANDLING
    // ==========================================================
    const keys = {};
    document.addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; });
    document.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

    // ==========================================================
    //   MAIN UPDATE LOOP
    // ==========================================================
    function update() {
        // 1. Process input
        // Throttle
        if (keys['w']) {
            state.throttle = Math.min(100, state.throttle + THROTTLE_STEP);
        }
        if (keys['s']) {
            state.throttle = Math.max(0, state.throttle - THROTTLE_STEP);
        }

        // Pitch
        if (keys['arrowup']) state.pitchRate = Math.min(5, state.pitchRate + PITCH_STEP);
        if (keys['arrowdown']) state.pitchRate = Math.max(-5, state.pitchRate - PITCH_STEP);
        // Yaw
        if (keys['arrowleft']) state.yawRate = Math.max(-5, state.yawRate - YAW_STEP);
        if (keys['arrowright']) state.yawRate = Math.min(5, state.yawRate + YAW_STEP);
        // Roll
        if (keys['a']) state.roll = Math.max(-5, state.rollRate - ROLL_STEP);
        if (keys['d']) state.rollRate = Math.min(5, state.rollRate + ROLL_STEP);

        // 2. Update physics
        // Simplified: speed depends on throttle and engine power
        const throttleFactor = state.throttle / 100;
        const desiredSpeed = throttleFactor * MAX_SPEED;
        const speedChange = (desiredSpeed - state.speed) * 0.05;
        state.speed += speedChange * dt * 60; // smoothing

        // Altitude change from pitch
        const altitudeChange = Math.sin(state.pitch * Math.PI / 180) * state.speed * dt * 30; // arbitrary
        state.alt += altitudeChange;
        state.alt = Math.max(MIN_ALT, Math.min(MAX_ALT, state.alt));

        // Update orientation
        state.pitch += state.pitchRate * dt * 60;
        state.roll += state.rollRate * dt * 60;
        state.yaw = (state.yaw + state.yawRate * dt * 60) % 360;

        // 3. Fuel consumption
        state.fuel -= state.speed * 0.01 * dt * 60; // arbitrary consumption
        state.fuel = Math.max(0, state.fuel);

        // 4. Engine power in response to steep climb (bug)
        if (Math.abs(state.pitch) > 30 && state.throttle > 70) {
            bugs.engineFluct = true;
            state.enginePower = 1.0 + 0.1 * Math.sin(performance.now() * 0.01);
        } else {
            bugs.engineFluct = false;
            state.enginePower = 1.0;
        }

        // 5. G-force simulation
        const netG = Math.abs(state.speedChange || 0) * GAS;
        if (netG > 4) { // above 4g threshold
            bugs.instrumentLag = true;
            lagTimer += dt;
        } else {
            bugs.instrumentLag = false;
            lagTimer = 0;
        }

        // 6. Altimeter stickiness bug at 2000-2100 ft
        if (state.alt > 1900 && state.alt < 2100) {
            bugs.altStuck = true;
            altStickTimer += dt;
        } else {
            bugs.altStuck = false;
            altStickTimer = 0;
        }

        // 7. Compass deviation near magnetic anomalies
        const headingMod = state.yaw % 360;
        if (MAG_ANECHO.some(h => Math.abs(headingMod - h) < 5)) {
            bugs.compassDrift = true;
            compassTimer += dt;
        } else {
            bugs.compassDrift = false;
            compassTimer = 0;
        }

        // 8. Update instrument readings with bugs
        // Slow ship instrument lag
        if (bugs.instrumentLag) {
            instruments.speed = lerp(instruments.speed, state.speed, 0.02);
            instruments.alt = lerp(instruments.alt, state.alt, 0.02);
        } else {
            instruments.speed = state.speed;
            instruments.alt = state.alt;
        }

        // Altimeter stickiness: use old reading until timer passes
        if (bugs.altStuck) {
            // keep old reading
        } else {
            // gradually recover
            instruments.alt = lerp(instruments.alt, state.alt, 0.1);
        }

        // Compass deviation
        if (bugs.compassDrift) {
            instruments.heading = (state.yaw + Math.sin(compassTimer * 3) * 10) % 360;
        } else {
            instruments.heading = state.yaw;
        }

        // Fuel & Throttle are direct
        instruments.fuel = state.fuel;
        instruments.throttle = state.throttle;
        instruments.enginePower = state.enginePower;

        // 9. Render
        render();

        // 10. Loop
        requestAnimationFrame(update);
    }

    // ==========================================================
    //   RENDERING
    // ==========================================================
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw background
        ctx.fillStyle = '#003399'; // sky
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Horizon
        const horizonY = 250 - (state.alt / 2000) * 50 + Math.sin(state.roll * Math.PI / 180) * 10;
        ctx.save();
        ctx.translate(250, horizonY);
        ctx.rotate(state.roll * Math.PI / 180);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-250, 0);
        ctx.lineTo(250, 0);
        ctx.stroke();
        ctx.restore();

        // Simple terrain line below horizon
        ctx.strokeStyle = '#555555';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, horizonY);
        ctx.lineTo(500, horizonY);
        ctx.stroke();

        // Aircraft symbol
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(250 - 10, 250);
        ctx.lineTo(250 + 10, 250);
        ctx.moveTo(250, 250 - 10);
        ctx.lineTo(250, 250 + 10);
        ctx.stroke();

        // HUD
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fillRect(0, 400, 500, 100);
        ctx.fillStyle = '#FFFFFF';
        ctx.font = '14px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`Speed: ${Math.round(instruments.speed)} kt`, 10, 420);
        ctx.fillText(`Altitude: ${Math.round(instruments.alt)} ft`, 10, 440);
        ctx.fillText(`Heading: ${Math.round(instruments.heading)}°`, 10, 460);
        ctx.fillText(`Throttle: ${Math.round(instruments.throttle)}%`, 10, 480);
        ctx.fillText(`Fuel: ${Math.round(instruments.fuel)} L`, 10, 500);

        // Visual bug indicators
        // Instrument lag
        if (bugs.instrumentLag) {
            ctx.fillStyle = 'rgba(255,0,0,0.5)';
            ctx.fillRect(450, 410, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Lag', 470, 425);
        }
        // Altimeter stuck
        if (bugs.altStuck) {
            ctx.fillStyle = 'rgba(255,255,0,0.5)';
            ctx.fillRect(450, 440, 40, 20);
            ctx.fillStyle = '#000000';
            ctx.fillText('Stuck', 470, 455);
        }
        // Compass drift
        if (bugs.compassDrift) {
            ctx.fillStyle = 'rgba(0,0,255,0.5)';
            ctx.fillRect(450, 470, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Drift', 470, 485);
        }
        // Engine fluctuation
        if (bugs.engineFluct) {
            ctx.fillStyle = 'rgba(255,0,255,0.5)';
            ctx.fillRect(450, 500, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Fluct', 470, 515);
        }
    }

    // ==========================================================
    //   HELPERS
    // ==========================================================
    function lerp(a, b, t) {
        return a + (b - a) * t;
    }

    // ==========================================================
    //   START
    // ==========================================================
    requestAnimationFrame(update);
}
